            assertNotNull(ref = getOneAndOnlyAssignment());

            beforeEveryMethod();
            add(Reference(ref));
            assertNotNull(ref = getOneAndOnlyAssignment());

            afterEachMethodCall();
            assertNotNull(ref = getOneAndOnlyAssignment());
        }
