import org.junit.Test;

public class TestConnectionRequestWrapper extends JUnit4 beforeClass {
    @AfterConstructor
    public void afterSetUp(Classed<R> wrapped, String name,
            String desc) {
        super(wrapped).attach(wrapped.wrap(name, desc)).afterSetUp();
    }
}

